/**
 * Rebuilds src/presets.json from the live Meson Explorer bundle.
 *
 * The explorer ships its chain/token tables inside a webpack chunk rather than serving them from an endpoint, so we locate the chunk that contains "shortSlip44" and lift the chain objects straight out of it.
 *
 * Run this whenever Meson adds a chain or token and the bot starts showing "Unknown chain" / "token#NN".
 */
// ----- Contents (generated by `npm run index` — do not edit) -----
// L22   text()
// L29   endOfObject()
// L48   extractChains()
// L62   isTestnet()
// L64   main()
// ----- end of contents -----

import { writeFile } from 'node:fs/promises'

const ORIGIN = 'https://explorer.meson.fi'
const BACKSLASH = String.fromCharCode(92)
const TESTNET = /testnet|devnet|ropsten|goerli|sepolia|holesky|fuji|mumbai|amoy/i

async function text (url) {
  const res = await fetch(url, { headers: { 'user-agent': 'meson-ticket-bot/presets' } })
  if (!res.ok) throw new Error(`${res.status} ${res.statusText} for ${url}`)
  return res.text()
}

/** Find the end index of the JSON value starting at `start` (must be '{'). */
function endOfObject (s, start) {
  let depth = 0
  let inStr = false
  let esc = false
  for (let i = start; i < s.length; i++) {
    const c = s[i]
    if (inStr) {
      if (esc) esc = false
      else if (c === BACKSLASH) esc = true
      else if (c === '"') inStr = false
      continue
    }
    if (c === '"') inStr = true
    else if (c === '{') depth++
    else if (c === '}' && --depth === 0) return i + 1
  }
  return -1
}

function extractChains (js) {
  const found = []
  let i = 0
  while ((i = js.indexOf('{"id":"', i)) !== -1) {
    const end = endOfObject(js, i)
    if (end === -1) break
    let obj
    try { obj = JSON.parse(js.slice(i, end)) } catch { i++; continue }
    if (obj && typeof obj === 'object' && obj.shortSlip44) found.push(obj)
    i = end
  }
  return found
}

const isTestnet = (c) => TESTNET.test(c.id) || TESTNET.test(c.name ?? '')

async function main () {
  const html = await text(`${ORIGIN}/`)
  const chunks = [...new Set([...html.matchAll(/\/_next\/static\/chunks\/[\w/.-]+\.js/g)].map((m) => m[0]))]
  if (!chunks.length) throw new Error('no webpack chunks found on the explorer homepage')

  const chains = {}
  let hits = 0
  for (const path of chunks) {
    let js
    try { js = await text(ORIGIN + path) } catch { continue }
    if (!js.includes('"shortSlip44"')) continue
    hits++
    // Later definitions win: the bundle carries an older preset generation first, then the current one (which uses the live token indexes).
    for (const c of extractChains(js)) {
      if (isTestnet(c)) continue
      chains[c.shortSlip44.toLowerCase()] = {
        id: c.id,
        name: c.name,
        alias: c.alias ?? null,
        explorer: c.explorer ?? null,
        addressFormat: c.addressFormat ?? null,
        tokens: Object.fromEntries((c.tokens ?? []).map((t) => [String(t.tokenIndex), t.symbol])),
      }
    }
  }

  if (!hits) throw new Error('no chunk contained the preset table — the explorer bundle layout changed')
  const count = Object.keys(chains).length
  if (count < 40) throw new Error(`only ${count} chains extracted, refusing to write a truncated table`)

  const out = { generatedAt: new Date().toISOString(), source: ORIGIN, chains }
  await writeFile(new URL('../src/presets.json', import.meta.url), JSON.stringify(out, null, 1) + '\n')
  console.log(`wrote src/presets.json — ${count} chains from ${hits} chunk(s)`)
}

main().catch((err) => { console.error(err.message); process.exit(1) })
